import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.DPaNRfRs.js";var i=JSON.parse(`{"title":"@sqlrooms/mcp","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://sqlrooms.org/api/mcp/"}]]},"headers":[],"relativePath":"api/mcp/index.md","filePath":"api/mcp/index.md"}`),a={name:`api/mcp/index.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /api/mcp.md for this page in Markdown format</div><h1 id="sqlrooms-mcp" tabindex="-1">@sqlrooms/mcp <a class="header-anchor" href="#sqlrooms-mcp" aria-label="Permalink to “@sqlrooms/mcp”">​</a></h1><h1 id="sqlrooms-mcp-1" tabindex="-1"><code>@sqlrooms/mcp</code> <a class="header-anchor" href="#sqlrooms-mcp-1" aria-label="Permalink to “@sqlrooms/mcp”">​</a></h1><blockquote><p><strong>Experimental:</strong> This package&#39;s API and behavior may change between releases.</p></blockquote><p>Transport-neutral room capabilities and the internal browser RPC protocol used by SQLRooms MCP hosts.</p><p>The core runtime owns catalog ordering, JSON Schema validation, invocation policy, cancellation, timeouts, and JSON-serializable results. It does not depend on React, browser globals, FastAPI, Electron, or an AI SDK.</p><p>Public entry points:</p><ul><li><code>@sqlrooms/mcp</code> exports the transport-neutral runtime and capability types.</li><li><code>@sqlrooms/mcp/browser</code> registers the authenticated browser bridge.</li><li><code>@sqlrooms/mcp/protocol</code> exports the versioned internal bridge schemas.</li></ul><p>The browser entry point adapts the runtime to SQLRooms&#39; authenticated host-to- page WebSocket. That WebSocket is application plumbing: public MCP requests remain stateless and the live browser room store remains authoritative.</p><p>The CLI asks the user to allow each MCP <code>query</code> call. That approval and the single-<code>SELECT</code> parser check are guardrails, not a SQL sandbox: approved DuckDB SQL can still access host resources through functions or extensions. Hosts embedding this package must isolate or restrict their query connector when untrusted SQL requires a true host-side security boundary.</p><p>The internal browser bridge protocol is version <code>1</code> in both TypeScript (<code>MCP_BRIDGE_PROTOCOL_VERSION</code>) and Python (<code>mcp_bridge.py</code>). Any wire-format change must update both definitions together. This is separate from the public MCP Streamable HTTP protocol negotiated by the official MCP SDK.</p><p>WebMCP is not implemented. A future adapter can map portable capability definitions to <code>document.modelContext.registerTool()</code> without changing the runtime or capability handlers.</p><h2 id="type-aliases" tabindex="-1">Type Aliases <a class="header-anchor" href="#type-aliases" aria-label="Permalink to “Type Aliases”">​</a></h2><ul><li><a href="./type-aliases/JsonSchema.html">JsonSchema</a></li><li><a href="./type-aliases/RoomCapabilityAnnotations.html">RoomCapabilityAnnotations</a></li><li><a href="./type-aliases/RoomCapabilityContext.html">RoomCapabilityContext</a></li><li><a href="./type-aliases/RoomCapabilitySuccess.html">RoomCapabilitySuccess</a></li><li><a href="./type-aliases/RoomCapabilityFailure.html">RoomCapabilityFailure</a></li><li><a href="./type-aliases/RoomCapabilityResult.html">RoomCapabilityResult</a></li><li><a href="./type-aliases/RoomCapability.html">RoomCapability</a></li><li><a href="./type-aliases/RoomCapabilityDescriptor.html">RoomCapabilityDescriptor</a></li><li><a href="./type-aliases/RoomCapabilityPolicyDecision.html">RoomCapabilityPolicyDecision</a></li><li><a href="./type-aliases/RoomCapabilityPolicy.html">RoomCapabilityPolicy</a></li><li><a href="./type-aliases/RoomCapabilityTrace.html">RoomCapabilityTrace</a></li><li><a href="./type-aliases/CreateRoomCapabilityRuntimeOptions.html">CreateRoomCapabilityRuntimeOptions</a></li><li><a href="./type-aliases/RoomCapabilityRuntime.html">RoomCapabilityRuntime</a></li></ul><h2 id="functions" tabindex="-1">Functions <a class="header-anchor" href="#functions" aria-label="Permalink to “Functions”">​</a></h2><ul><li><a href="./functions/createRoomCapabilityRuntime.html">createRoomCapabilityRuntime</a></li></ul>`,16)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};